    def largestRectangleArea(self, height):
        areas = {}
        sorted_height = sorted(list(set(height)))
        lh = len(height)
        for i in range(lh):
            h = height[lh-1-i]
            areas[lh-1-i] = {}
            j = 0
            while sorted_height[j] <= h:
